#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <ctype.h>

#define MAX_URL_LEN 2048
#define MAX_LOG_LEN 4096
#define ALLOWED_HOSTS_COUNT 3

static const char *allowed_hosts[] = {
    "app.example.com",
    "cdn.example.com",
    "api.example.com"
};

typedef struct {
    int fd;
    char session_id[64];
    char remote_addr[46];
    int authenticated;
} ws_client_t;

typedef struct {
    char url[MAX_URL_LEN];
    char host[256];
    char path[1024];
    int port;
    int uses_tls;
} parsed_url_t;

static void audit_log(const ws_client_t *client, const char *action, const char *detail) {
    time_t now = time(NULL);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
    fprintf(stderr, "[AUDIT] %s client=%s addr=%s action=%s detail=%.512s\n",
            timestamp, client->session_id, client->remote_addr, action, detail);
}

static int normalize_host(const char *raw_host, char *out, size_t out_len) {
    size_t len = strlen(raw_host);
    if (len == 0 || len >= out_len) return -1;

    /* Convert to lowercase for comparison */
    for (size_t i = 0; i < len; i++) {
        out[i] = (char)tolower((unsigned char)raw_host[i]);
    }
    out[len] = '\0';

    /* Strip trailing dot (FQDN normalization) */
    if (len > 0 && out[len - 1] == '.') {
        out[len - 1] = '\0';
    }
    return 0;
}

static int parse_url(const char *url, parsed_url_t *parsed) {
    memset(parsed, 0, sizeof(*parsed));

    if (strlen(url) >= MAX_URL_LEN) return -1;
    strncpy(parsed->url, url, MAX_URL_LEN - 1);

    const char *p = url;

    /* Detect scheme */
    if (strncmp(p, "https://", 8) == 0) {
        parsed->uses_tls = 1;
        parsed->port = 443;
        p += 8;
    } else if (strncmp(p, "http://", 7) == 0) {
        parsed->uses_tls = 0;
        parsed->port = 80;
        p += 7;
    } else {
        /* Relative URL or protocol-relative */
        if (p[0] == '/' && p[1] == '/') {
            p += 2;
            parsed->uses_tls = 1;
            parsed->port = 443;
        } else if (p[0] == '/') {
            /* Relative path - safe */
            strncpy(parsed->host, "self", sizeof(parsed->host) - 1);
            strncpy(parsed->path, p, sizeof(parsed->path) - 1);
            return 0;
        } else {
            return -1;
        }
    }

    /* Reject URLs containing userinfo (@ before first /) */
    const char *first_slash = strchr(p, '/');
    const char *at_sign = strchr(p, '@');
    if (at_sign && (!first_slash || at_sign < first_slash)) {
        return -1; /* Reject userinfo in URL - potential open redirect */
    }

    /* Extract host */
    const char *host_start = p;
    const char *host_end = NULL;

    /* Find end of host (port separator, path, or end of string) */
    const char *colon = strchr(p, ':');
    const char *slash = strchr(p, '/');

    if (colon && (!slash || colon < slash)) {
        host_end = colon;
        parsed->port = atoi(colon + 1);
    } else if (slash) {
        host_end = slash;
    } else {
        host_end = host_start + strlen(host_start);
    }

    size_t host_len = (size_t)(host_end - host_start);
    if (host_len >= sizeof(parsed->host)) return -1;
    memcpy(parsed->host, host_start, host_len);
    parsed->host[host_len] = '\0';

    /* Validate host contains only valid characters */
    for (size_t i = 0; i < host_len; i++) {
        char c = parsed->host[i];
        if (!isalnum((unsigned char)c) && c != '.' && c != '-') {
            return -1;
        }
    }

    /* Extract path */
    if (slash) {
        strncpy(parsed->path, slash, sizeof(parsed->path) - 1);
    } else {
        strcpy(parsed->path, "/");
    }

    return 0;
}

static int is_host_allowed(const char *host) {
    char normalized[256];
    if (normalize_host(host, normalized, sizeof(normalized)) != 0) {
        return 0;
    }

    for (int i = 0; i < ALLOWED_HOSTS_COUNT; i++) {
        /* Check exact match */
        size_t norm_len = strlen(normalized);
        size_t allowed_len = strlen(allowed_hosts[i]);

        if (norm_len == allowed_len && strcmp(normalized, allowed_hosts[i]) == 0) {
            return 1;
        }
        /* Also allow subdomains: *.example.com */
        if (norm_len > allowed_len + 1) {
            size_t offset = norm_len - allowed_len;
            if (normalized[offset - 1] == '.' &&
                strcmp(normalized + offset, allowed_hosts[i]) == 0) {
                return 1;
            }
        }
    }
    return 0;
}

static int validate_redirect_target(const parsed_url_t *parsed) {
    /* Self-referential paths are always safe */
    if (strcmp(parsed->host, "self") == 0) {
        return 1;
    }

    /* Must use TLS */
    if (!parsed->uses_tls) {
        return 0;
    }

    /* Host must be in allowlist */
    return is_host_allowed(parsed->host);
}

typedef struct {
    char type[32];
    char payload[MAX_URL_LEN];
} ws_message_t;

static int parse_ws_message(const char *raw, size_t len, ws_message_t *msg) {
    memset(msg, 0, sizeof(*msg));
    /* Simple JSON-like parsing: {"type":"...","url":"..."} */
    const char *type_key = strstr(raw, "\"type\"");
    const char *url_key = strstr(raw, "\"url\"");

    if (!type_key) return -1;

    const char *type_val = strchr(type_key + 6, '"');
    if (!type_val) return -1;
    type_val++;
    const char *type_end = strchr(type_val, '"');
    if (!type_end || (size_t)(type_end - type_val) >= sizeof(msg->type)) return -1;
    memcpy(msg->type, type_val, (size_t)(type_end - type_val));

    if (url_key) {
        const char *url_val = strchr(url_key + 5, '"');
        if (!url_val) return -1;
        url_val++;
        const char *url_end = strchr(url_val, '"');
        if (!url_end || (size_t)(url_end - url_val) >= sizeof(msg->payload)) return -1;
        memcpy(msg->payload, url_val, (size_t)(url_end - url_val));
    }
    return 0;
}

int handle_redirect_request(ws_client_t *client, const char *raw_msg, size_t msg_len) {
    ws_message_t msg;
    parsed_url_t parsed;
    char response[MAX_URL_LEN + 128];

    if (!client->authenticated) {
        audit_log(client, "REDIRECT_DENIED", "unauthenticated");
        return -1;
    }

    if (parse_ws_message(raw_msg, msg_len, &msg) != 0) {
        audit_log(client, "REDIRECT_DENIED", "malformed_message");
        return -1;
    }

    if (strcmp(msg.type, "redirect") != 0) {
        return 0; /* Not a redirect message */
    }

    audit_log(client, "REDIRECT_REQUESTED", msg.payload);

    if (parse_url(msg.payload, &parsed) != 0) {
        audit_log(client, "REDIRECT_DENIED", "invalid_url");
        return -1;
    }

    if (!validate_redirect_target(&parsed)) {
        audit_log(client, "REDIRECT_DENIED", parsed.host);
        return -1;
    }

    audit_log(client, "REDIRECT_APPROVED", parsed.url);

    /* Send redirect response back over WebSocket */
    snprintf(response, sizeof(response),
             "{\"type\":\"redirect\",\"location\":\"%s\"}", parsed.url);

    /* In real code: ws_send(client->fd, response, strlen(response)); */
    printf("SEND[%s]: %s\n", client->session_id, response);
    return 0;
}

/* Test harness */
int main(void) {
    ws_client_t client = {
        .fd = 1,
        .session_id = "sess_abc123",
        .remote_addr = "192.168.1.100",
        .authenticated = 1
    };

    /* Test: legitimate redirect */
    const char *msg1 = "{\"type\":\"redirect\",\"url\":\"https://app.example.com/dashboard\"}";
    handle_redirect_request(&client, msg1, strlen(msg1));

    /* Test: blocked external redirect */
    const char *msg2 = "{\"type\":\"redirect\",\"url\":\"https://evil.com/phish\"}";
    handle_redirect_request(&client, msg2, strlen(msg2));

    /* Test: subdomain allowed */
    const char *msg3 = "{\"type\":\"redirect\",\"url\":\"https://sub.app.example.com/page\"}";
    handle_redirect_request(&client, msg3, strlen(msg3));

    /* Test: bypass via userinfo - BLOCKED */
    const char *msg4 = "{\"type\":\"redirect\",\"url\":\"https://app.example.com@evil.com/steal\"}";
    handle_redirect_request(&client, msg4, strlen(msg4));

    return 0;
}
